import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { TranslationJob } from '../src/image-translation.js';
import { DENSITY_FIELD } from '../src/density-field.js';
import { densityImage } from './helpers/density-fixtures.js';

// Measured from the previous phone-tested commit, not regenerated by this test.
const baseline=JSON.parse(readFileSync(new URL('./fixtures/fusion-volume-baseline.json',import.meta.url)));
const make=name=>new TranslationJob().run(densityImage(name),{yieldTask:async()=>{}});
const digest=x=>createHash('sha256').update(JSON.stringify(x)).digest('hex');

test('volume changes preserve the prior density field, weights and every sampled UV/cell',async()=>{
 for(const [name,prior]of Object.entries(baseline.images)){
  const m=await make(name);
  assert.equal(digest([...m.field.density].map(v=>Math.round(v*1e6))),prior.field,name);
  assert.equal(digest(m.cached.map(p=>[p.cell,...p.uv.map(v=>Math.round(v*1e6)),Math.round(p.density*1e6)])),prior.samples,name);
  assert.deepEqual(m.field.weights,prior.weights,name);
 }
});

test('ring, corner and separated subjects gain populated front/back depth instead of just a distant outlier',async()=>{
 for(const name of ['ring','corner','clusters']){
  const m=await make(name),prior=baseline.images[name],z=m.cached.map(p=>p.point[2]);
  const rms=Math.sqrt(z.reduce((s,v)=>s+v*v,0)/z.length);
  assert.ok(rms>prior.zRMS*1.1,name);
  assert.ok(z.filter(v=>v>.15).length>z.length*.2,name);
  assert.ok(z.filter(v=>v<-.15).length>z.length*.2,name);
  assert.ok(Math.max(...z)-Math.min(...z)>=prior.zSpan,name);
 }
});

test('cross-depth links and slanted shared-node facets increase without a reference cage or larger budgets',async()=>{
 for(const name of ['ring','corner','clusters']){
  const m=await make(name),prior=baseline.images[name],z=m.cached.map(p=>p.point[2]);
  assert.ok(m.mesh.links.filter(([a,b])=>Math.abs(z[a]-z[b])>.08).length>prior.crossDepth*1.3,name);
  const slanted=m.mesh.triangles.filter(t=>Math.max(...t.map(i=>z[i]))-Math.min(...t.map(i=>z[i]))>=DENSITY_FIELD.depthFaceSpan);
  assert.ok(slanted.length>prior.slantedFaces,name);
  assert.ok(m.mesh.links.length<=DENSITY_FIELD.mobile.lines);
  assert.ok(m.mesh.triangles.length<=DENSITY_FIELD.mobile.faces);
  assert.ok(m.stats.areaRatio<=DENSITY_FIELD.faceAreaRatio);
  assert.equal(new Set(m.mesh.triangles.map(t=>t.join(','))).size,m.mesh.triangles.length);
  assert.ok(m.mesh.primary.every(v=>!v));assert.ok(m.cached.every(p=>!p.pinned&&!p.baseVertex));
  assert.equal(m.cached.length,baseline.count);
  for(const [a,b,c]of m.mesh.triangles){
   assert.equal(m.mesh.nodes[a],m.cached[a].point);
   assert.ok(m.mesh.adjacency[a].includes(b)&&m.mesh.adjacency[b].includes(c)&&m.mesh.adjacency[c].includes(a));
  }
 }
});

test('local depth preserves the central peak and is neither uniform Z stretching nor a constant peripheral slab',async()=>{
 const m=await make('ring'),n=m.field.resolution;
 const cell=(u,v)=>Math.min(n-1,Math.floor(v*n))*n+Math.min(n-1,Math.floor(u*n));
 const center=m.embed(.5,.5,1,cell(.5,.5));
 // At the reference pole the local addition vanishes, preserving its old depth.
 const i=cell(.5,.5),f=m.field;
 const oldCenter=(.18+.24*f.foreground[i]+.14*f.density[i]+.08*f.coarse[i]+(f.coarse[i]-m.features.mean)*.06)*(1-DENSITY_FIELD.depthMix)
  +DENSITY_FIELD.depthMix*(.88+.12*f.density[i]);
 assert.ok(Math.abs(center[2]-oldCenter)<1e-12);
 const probes=[[.7,.5],[.8,.5],[.8,.7],[.95,.9]].map(([u,v])=>m.embed(u,v,1,cell(u,v))[2]);
 assert.ok(new Set(probes.map(v=>Math.round(v*1000))).size===probes.length);
 assert.ok(probes[0]>probes[1]&&probes[1]>probes[3]);
});
